using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
namespace VisionUi;
// DynamicRunParamDisplayWin -> ConfirmBaseWindow: no cancel, 34px footer, 66x24 confirm.
public class SourceConfirmWindow:Window {
 protected readonly TextBlock Error=new(){Foreground=Brushes.DarkRed,VerticalAlignment=VerticalAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis};
 protected void SetMainContent(FrameworkElement body,Action confirm){Width=1000;Height=600;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;WindowStartupLocation=WindowStartupLocation.CenterOwner;ShowInTaskbar=false;FontFamily=new("Microsoft YaHei UI");FontSize=14;Background=new SolidColorBrush(Color.FromRgb(242,243,245));Foreground=new SolidColorBrush(Color.FromRgb(78,80,84));var grid=new Grid();grid.RowDefinitions.Add(new(){Height=new(33)});grid.RowDefinitions.Add(new());grid.RowDefinitions.Add(new(){Height=new(34)});var caption=new DockPanel{Background=new SolidColorBrush(Color.FromRgb(38,38,38))};var close=new Button{Content="×",Width=40,Background=Brushes.Transparent,Foreground=Brushes.LightGray,BorderThickness=new(0)};DockPanel.SetDock(close,Dock.Right);close.Click+=(_,_)=>Close();caption.Children.Add(close);var title=new TextBlock{Margin=new(10,0,0,0),Foreground=Brushes.White,VerticalAlignment=VerticalAlignment.Center};title.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding(nameof(Title)){Source=this});caption.Children.Add(title);caption.MouseLeftButtonDown+=(_,e)=>{if(e.LeftButton==MouseButtonState.Pressed)DragMove();};grid.Children.Add(caption);Grid.SetRow(body,1);grid.Children.Add(body);var footer=new DockPanel{Background=new SolidColorBrush(Color.FromRgb(228,229,231))};var button=new Button{Content="确定",Tag="ImageBinaryRoiConfirm",Width=66,Height=24,Margin=new(15,0,0,0),VerticalAlignment=VerticalAlignment.Center};button.Click+=(_,_)=>{try{confirm();DialogResult=true;}catch(Exception e){Error.Text=e.Message;}};DockPanel.SetDock(button,Dock.Right);footer.Children.Add(button);footer.Children.Add(Error);Grid.SetRow(footer,2);grid.Children.Add(footer);Content=new Border{BorderThickness=new(0,1,0,0),BorderBrush=new SolidColorBrush(Color.FromRgb(253,79,65)),Child=grid};}
}
